apiNamespace files {
  middlewareConfigFn: import { filesMiddlewareConfig } from "@src/middleware",
  path: "/files"
}

api uploadFile {
  fn: import { uploadFile } from "@src/api",
  httpRoute: (POST, "/files/upload"),
  auth: true,
  entities: [File]
}

api downloadFile {
  fn: import { downloadFile } from "@src/api",
  httpRoute: (GET, "/files/:id/download"),
  auth: true,
  entities: [File]
}

